import { GitLabContextJsonSchema } from '@gitlab-mfe/context';
// GitLabContextJsonSchema uses JSON Schema Draft 2020-12 (generated by Zod's toJSONSchema).
// AJV v8's default instance only supports Draft-07; import from ajv/dist/2020 for 2020-12.
import Ajv from 'ajv/dist/2020';
import duoChatPackage from '@gitlab-mfe/duo-chat/package.json';
import { buildGitLabContext } from '~/mfe_loader';
import rootPackage from '../../../package.json';

// Minimal DOM scaffolding that mirrors what the monolith renders:
//   #js-mfe-foo{ data: { project_full_path: "g/p", project_id: "1" } }
function makeMountElement(dataset = {}) {
  const el = document.createElement('div');
  Object.assign(el.dataset, dataset);
  return el;
}

function mockGon(overrides = {}) {
  window.gon = {
    current_user_id: 42,
    current_username: 'jsmith',
    current_user_fullname: 'John Smith',
    current_user_avatar_url: 'https://example.com/avatar.png',
    features: { mfeDuoChatPoc: true },
    licensed_features: { aiFeatures: true },
    api_version: 'v4',
    relative_url_root: '',
    gitlab_url: 'https://gitlab.com',
    sentry_dsn: null,
    sentry_environment: null,
    ...overrides,
  };
}

function mockCsrf(token = 'test-csrf-token') {
  const meta = document.createElement('meta');
  meta.name = 'csrf-token';
  meta.content = token;
  document.head.appendChild(meta);
}

describe('buildGitLabContext', () => {
  let validate;

  beforeAll(() => {
    validate = new Ajv().compile(GitLabContextJsonSchema);
  });

  beforeEach(() => {
    mockGon();
    mockCsrf();
    document.documentElement.lang = 'en';
  });

  afterEach(() => {
    window.gon = undefined;
    document.head.querySelector('meta[name="csrf-token"]')?.remove();
    document.documentElement.removeAttribute('lang');
  });

  it('returns an object that satisfies GitLabContextSchema', () => {
    const el = makeMountElement({ projectFullPath: 'my-group/my-project', projectId: '1' });
    const context = buildGitLabContext(el);

    expect(context).toValidateJsonSchema(validate);
  });

  it('falls back to defaults when gon, the CSRF token and <html lang> are missing', () => {
    window.gon = undefined;
    document.head.querySelector('meta[name="csrf-token"]').remove();
    document.documentElement.removeAttribute('lang');

    const context = buildGitLabContext(makeMountElement());

    expect(context).toEqual({
      currentUser: null,
      features: {},
      licensedFeatures: {},
      locale: 'en',
      csrfToken: '',
      apiVersion: 'v4',
      relativeUrlRoot: '',
      gitlabUrl: window.location.origin,
      sentryDsn: null,
      sentryEnvironment: null,
      pageData: {},
    });
    expect(context).toValidateJsonSchema(validate);
  });

  it('sets currentUser to null when gon has no current_user_id', () => {
    mockGon({ current_user_id: undefined });
    const context = buildGitLabContext(makeMountElement());

    expect(context.currentUser).toBeNull();
    expect(context).toValidateJsonSchema(validate);
  });

  it('reads locale from <html lang>', () => {
    document.documentElement.lang = 'fr';
    const context = buildGitLabContext(makeMountElement());

    expect(context.locale).toBe('fr');
  });

  it('spreads el.dataset into pageData', () => {
    const el = makeMountElement({ projectFullPath: 'g/p', namespaceFullPath: 'g' });
    const context = buildGitLabContext(el);

    expect(context.pageData).toEqual({ projectFullPath: 'g/p', namespaceFullPath: 'g' });
  });

  // A @gitlab-mfe/duo-chat bump could nest a newer @gitlab-mfe/context, and this
  // spec would keep validating against the old schema.
  it('uses the @gitlab-mfe/context version that @gitlab-mfe/duo-chat depends on', () => {
    expect(rootPackage.dependencies['@gitlab-mfe/context']).toBe(
      duoChatPackage.dependencies['@gitlab-mfe/context'],
    );
  });
});
